insert into public.integration_catalog (key,display_name,category,provider,active,setup_status,capabilities,sort_order,metadata,description,toolkit_slug,auth_config_ref,updated_at) values ('cloudflare-workers-ai','Cloudflare Workers AI','AI & Generation','cloudflare',true,'setup_required',array['Image generation'],60,jsonb_build_object('model','@cf/black-forest-labs/flux-1-schnell','free_allocation','10000 neurons/day','credential_env',array['CLOUDFLARE_ACCOUNT_ID','CLOUDFLARE_API_TOKEN']),'Curatia visual generation through Cloudflare Workers AI.','workers-ai',null,now()) on conflict (key) do update set display_name=excluded.display_name,category=excluded.category,provider=excluded.provider,active=excluded.active,capabilities=excluded.capabilities,metadata=excluded.metadata,description=excluded.description,toolkit_slug=excluded.toolkit_slug,updated_at=now();
